package main
import ("log";"net/http";"os")
func main(){p:=os.Getenv("PORT");if p==""{p="10000"};http.HandleFunc("/",func(w http.ResponseWriter,r *http.Request){w.Header().Set("Content-Type","text/html; charset=utf-8");w.Write([]byte(html))});log.Println(p);http.ListenAndServe(":"+p,nil)}
const html=
"<!doctype html><meta charset=utf-8><meta name=viewport content='width=device-width'><title>U</title><script src='https://unpkg.com/xlsx@0.18.5/dist/xlsx.full.min.js'></script><header style='background:#1a6d2f;color:#fff;padding:8px;text-align:center;font-weight:900'>Uwashusema Mahida</header><div style='padding:4px'><div style='display:flex;gap:2px'><select id=m><option value=11>Nov<option value=12>Des</select><input id=y type=number value=2026><button onclick=R()>Sawa</button></div><div style='display:flex;gap:2px'><div style='flex:1;background:#2e7d32;color:#fff;padding:4px;text-align:center'>MAPATO<br><span id=a>0</span></div><div style='flex:1;background:#c00;color:#fff;padding:4px;text-align:center'>MATUMIZI<br><span id=b>0</span></div><div style='flex:1;background:#1565c0;color:#fff;padding:4px;text-align:center'>SALIO<br><span id=c>0</span></div></div><div style='background:#fff;padding:4px'><b>Wanachama <button onclick=W() style='float:right'>+ Mpya</button></b><div id=wl></div></div><div style='background:#fff;padding:4px'><select id=sw></select><select id=sa><option value=hisa>Hisa<option value=ada>Ada<option value=marejesho>Marejesho<option value=faini_ada>Riba Ada<option value=faini_marejesho>Riba Rejesho<option value=michango>Michango<option value=mkopo_toka>Mkopo</select><input id=kv type=number placeholder=Kiasi><button onclick=M()>Hifadhi</button><div id=ca style=color:green></div></div><div style='background:#fff;padding:4px'><button onclick=E() style='background:#1565c0;color:#fff;width:100%'>Pakua Excel (4)</button><div id=hi></div></div></div><script>D=JSON.parse(localStorage.getItem('v6')||'null')||{w:[],m:[]};function S(){localStorage.setItem('v6',JSON.stringify(D));R()}function W(){j=prompt('Jina:');if(j){D.w.push({j:j});S()}}function M(){w=sw.value;a=sa.value;k=+kv.value;if(!w||!k)return alert('Jaza');D.m.push({w:w,a:a,k:k,mm:+m.value,yy:+y.value});if(a=='mkopo_toka'){f=Math.round(k*0.05);D.m.push({w:w,a:'fomu',k:f,mm:+m.value,yy:+y.value})}kv.value='';S()}function R(){mm=+m.value;yy=+y.value;mi=D.m.filter(x=>x.mm==mm&&x.yy==yy);mp=0;mt=0;mi.forEach(t=>{if(['hisa','ada','marejesho','faini_ada','faini_marejesho','fomu','michango'].includes(t.a))mp+=t.k;if(t.a=='mkopo_toka')mt+=t.k});a.innerText=mp;b.innerText=mt;c.innerText=mp-mt;wl.innerHTML=sw.innerHTML='';if(!D.w.length)wl.innerHTML='Hakuna';D.w.forEach((x,i)=>{wl.innerHTML+=x.j+' <button onclick=\"D.w.splice('+i+',1);S()\">X</button><br>';sw.innerHTML+='<option>'+x.j+'</option>'});hi.innerHTML='';mi.slice().reverse().forEach(t=>{hi.innerHTML+=t.w+'-'+t.a+'-'+t.k+'<br>'})}kvEl=kv;sa.onchange=()=>{k=+kvEl.value;ca.innerHTML=sa.value=='mkopo_toka'&&k>0?'Fomu AUTO='+Math.round(k*0.05):''};kvEl.oninput=()=>sa.onchange();function E(){all=D.m.filter(x=>x.mm==+m.value&&x.yy==+y.value);if(!all.length)return alert('Hakuna');r1=[['Jina','Ada','Riba']];r2=[['Jina','Mkopo','Fomu','Rejesho','Riba']];r3=[['Jina','Hisa']];r4=[['Jina','Michango']];am={};ar={};dm={};hm={};mc={};D.w.forEach(x=>{am[x.j]=0;ar[x.j]=0;dm[x.j]={c:0,f:0,r:0,fr:0};hm[x.j]=0;mc[x.j]=0});all.forEach(t=>{if(t.a=='ada')am[t.w]+=t.k;if(t.a=='faini_ada')ar[t.w]+=t.k;if(t.a=='mkopo_toka')dm[t.w].c+=t.k;if(t.a=='fomu')dm[t.w].f+=t.k;if(t.a=='marejesho')dm[t.w].r+=t.k;if(t.a=='faini_marejesho')dm[t.w].fr+=t.k;if(t.a=='hisa')hm[t.w]+=t.k;if(t.a=='michango')mc[t.w]+=t.k});for(j in am)r1.push([j,am[j],ar[j]]);for(j in dm){d=dm[j];if(d.c>0)r2.push([j,d.c,d.f,d.r,d.fr])}for(j in hm)if(hm[j])r3.push([j,hm[j]]);for(j in mc)if(mc[j])r4.push([j,mc[j]]);wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(r1),'Ada');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(r2),'Mikopo');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(r3),'Hisa');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(r4),'Michango');XLSX.writeFile(wb,'Uwashusema.xlsx')}m.value=11;R();</script>"
